请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-118

=== 用户原始指令 (query.txt) ===
给我做一个带浅色底纹的清理卡片，左边横着排几个大头相册、微信、视频的垃圾清理图标，底下配上固定不动的文字说明，右边整一个带紧迫感渐变色的“一键深度加速”按钮，点一下直接调起地图导航去最近的华为售后，同时要在顶部显眼位置读取天气数据，如果遇到取消清理的失败危险状态，必须用红色警告图标标出来提醒我。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我做一个带浅色底纹的清理卡片，左边横着排几个大头相册、微信、视频的垃圾清理图标，底下配上固定不动的文字说明，右边整一个带紧迫感渐变色的“一键深度加速”按钮，点一下直接调起地图导航去最近的华为售后，同时要在顶部显眼位置读取天气数据，如果遇到取消清理的失败危险状态，必须用红色警告图标标出来提醒我。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.maps",
        "abilityName": "com.huawei.maps.app.MapActivity",
        "uri": "mapapp://navigation?destination=nearest_huawei_service"
      }
    }
  ],
  "dataModel": {
    "value": {
      "weather": {
        "city": "深圳",
        "condition": "阵雨",
        "temperature": "29℃"
      },
      "clean": {
        "status": "取消清理失败",
        "riskLevel": "危险",
        "note": "相册 微信 视频垃圾待清理",
        "actionText": "一键深度加速",
        "items": [
          {
            "name": "相册",
            "icon": "assets/icons/memory_album.png"
          },
          {
            "name": "微信",
            "icon": "assets/icons/memory_wechat.png"
          },
          {
            "name": "视频",
            "icon": "assets/icons/memory_video.png"
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "album_icon",
      "src": "assets/icons/memory_album.png",
      "use": "cleanup category icon",
      "description": "相册垃圾清理图标，用于表示图片和相册缓存清理入口。",
      "bindTo": "/clean/items/0/icon"
    },
    {
      "assetRef": "wechat_icon",
      "src": "assets/icons/memory_wechat.png",
      "use": "cleanup category icon",
      "description": "微信缓存清理图标，用于表示聊天缓存和应用垃圾清理入口。",
      "bindTo": "/clean/items/1/icon"
    },
    {
      "assetRef": "video_icon",
      "src": "assets/icons/memory_video.png",
      "use": "cleanup category icon",
      "description": "视频垃圾清理图标，用于表示视频缓存和大文件清理入口。",
      "bindTo": "/clean/items/2/icon"
    }
  ]
}

